import{_ as r,C as i,o as l,c as n,ak as c,E as o,j as t,a}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"SignaturePad 签名板","description":"","frontmatter":{},"headers":[],"relativePath":"components/signature-pad.md","filePath":"components/signature-pad.md","lastUpdated":1790174783000}'),s={name:"components/signature-pad.md"};function h(g,d,u,b,p,x){const e=i("XhDemo");return l(),n("div",null,[d[0]||(d[0]=c('<h1 id="signaturepad-签名板" tabindex="-1">SignaturePad 签名板 <a class="header-anchor" href="#signaturepad-签名板" aria-label="Permalink to &quot;SignaturePad 签名板&quot;">​</a></h1><p>用指针书写的画布：按下落笔、移动成迹、抬起收笔，输出可缩放、可直接提交的 SVG。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/signature-pad" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/signature-pad.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/signature-pad" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/signature-pad" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/signature-pad.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一块画布加一条笔迹路径即可：按下落笔、移动成迹、抬起收笔</p>',5)),o(e,{src:"signature-pad/01-basic"}),d[1]||(d[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;signature-pad&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>control</code></strong> · <code>guide</code> · <strong><code>path</code></strong> · <code>clear-trigger</code> · <code>status</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="标题、基准线与清空" tabindex="-1">标题、基准线与清空 <a class="header-anchor" href="#标题、基准线与清空" aria-label="Permalink to &quot;标题、基准线与清空&quot;">​</a></h3><p>基准线是纯画面（带 aria-hidden），清空按钮是原生 button，读屏朗读的是 translations 中的文案</p>',6)),o(e,{src:"signature-pad/02-guide"}),d[2]||(d[2]=t("h3",{id:"参与表单",tabindex:"-1"},[a("参与表单 "),t("a",{class:"header-anchor",href:"#参与表单","aria-label":'Permalink to "参与表单"'},"​")],-1)),d[3]||(d[3]=t("p",null,"提供 name 后带上表单影子，提交的是一份独立 SVG；表单重置会把画布清空",-1)),o(e,{src:"signature-pad/03-form"}),d[4]||(d[4]=t("h3",{id:"笔迹外形",tabindex:"-1"},[a("笔迹外形 "),t("a",{class:"header-anchor",href:"#笔迹外形","aria-label":'Permalink to "笔迹外形"'},"​")],-1)),d[5]||(d[5]=t("p",null,"drawing 调整笔宽与压感：thinning 越大，划得越快笔画越细，simulatePressure 决定压感取设备值还是按速度计算",-1)),o(e,{src:"signature-pad/04-pen"}),d[6]||(d[6]=t("h3",{id:"只读与禁用",tabindex:"-1"},[a("只读与禁用 "),t("a",{class:"header-anchor",href:"#只读与禁用","aria-label":'Permalink to "只读与禁用"'},"​")],-1)),d[7]||(d[7]=t("p",null,"只读时已绘制的笔迹可见但不可修改，禁用时连清空按钮都不可按下；两者都使用原生 disabled，不只是视觉置灰",-1)),o(e,{src:"signature-pad/05-readonly-disabled"}),d[8]||(d[8]=t("h3",{id:"取出签名",tabindex:"-1"},[a("取出签名 "),t("a",{class:"header-anchor",href:"#取出签名","aria-label":'Permalink to "取出签名"'},"​")],-1)),d[9]||(d[9]=t("p",null,"签名定稿时 draw-end 带上一份可直接入库的 SVG；提交前用 empty 拦截一次，空签名不应离开客户端",-1)),o(e,{src:"signature-pad/06-export"}),d[10]||(d[10]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>承诺书、回执、验收单上需要手写签名。</li><li>交付确认、上门服务签收等需要留下确认痕迹的场景。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>需要已有的签名图片时，属于上传，使用<a href="./file-upload">文件上传</a>。</li><li>需要打字签名或姓名核对时，属于一行文本，使用<a href="./text-field">文本字段</a>。</li><li>需要在图片上圈画批注时，本组件只绘制自己的画布，不承载底图。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>笔迹是 SVG 填充路径，放大不模糊；每一笔是同一条路径上的一条子路径。</li><li>第一笔落下时测量一次画布并固定这套坐标，画布的 <code>viewBox</code> 与导出的 SVG 都使用它：容器变宽变窄时，已有笔迹跟随缩放而不是停留在原像素上错位。清空后重新测量。</li><li><code>drawing</code> 一组选项调整笔画外形：<code>size</code> 决定粗细，<code>thinning</code> 让粗细随压感变化，<code>simulatePressure</code> 决定压感取设备值还是按落笔速度计算。</li><li>带 <code>name</code> 即参与表单提交，提交的是一份独立的 SVG 文档；表单重置会清空画布。</li><li>笔迹变化时发出 <code>draw</code>，签名定稿时发出 <code>draw-end</code>：抬笔、点击清空、表单重置三条路径都发出。按 <code>draw-end</code> 缓存待提交的 SVG 不会取到过期版本。</li><li>指针划出画布甚至划出窗口都持续跟随，抬起即收笔；落笔的指针被捕获，手掌与第二根手指的移动不会续进这一笔。</li><li>画布是一块字段外壳：静息不填底 + <code>--xh-border-control</code> 描边 + 4px 控件圆角、无影；落笔时描边加深，只读只换淡底，禁用退到 <code>--xh-border-default</code> + <code>--xh-bg-subtle</code>。画布按宽高比撑高，吃不下字段家族配方钉死的控件行高，因此外壳按同一套字段规则自绘。</li><li>标签走字段标签档（14 / 500 / <code>--xh-fg-default</code>），贴画布 <code>--xh-space-1</code>；状态句是说明角色（13 / <code>--xh-fg-muted</code>）。</li><li>清空按钮走 Action Control text 档 sm：缺省 <code>outline</code> 描边，白底承载阶梯悬停 100 → 按下 200，按下缩放并换底；空画布时只把静息前景压淡，按钮照常可按。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与<a href="./field">表单字段</a>搭配：标题、说明与错误提示交给字段，签名板只负责画布。</li><li>放入<a href="./form">表单</a>，提供 <code>name</code> 后随表单提交与重置。</li><li>与<a href="./dialog">对话框</a>搭配做签名确认：确认按钮的可用状态读取 <code>empty</code>。</li></ul><h3 id="节点形状是硬约束" tabindex="-1">节点形状是硬约束 <a class="header-anchor" href="#节点形状是硬约束" aria-label="Permalink to &quot;节点形状是硬约束&quot;">​</a></h3><p>画布这一族部件必须落在特定标签上，写错不报错，但无法绘制：</p><ul><li><code>control</code> 必须是 <code>&lt;svg&gt;</code>；</li><li><code>guide</code> 必须是 <code>control</code> 内的 <code>&lt;line&gt;</code>；</li><li><code>path</code> 必须是 <code>control</code> 内的 <code>&lt;path&gt;</code>；</li><li><code>clear-trigger</code> 必须是原生 <code>&lt;button&gt;</code>，<code>hidden-input</code> 必须是原生 <code>&lt;input&gt;</code>。</li></ul><p><code>viewBox</code> 由组件写入，作者不要在 <code>control</code> 上再写。</p><h3 id="两个适配器的分工" tabindex="-1">两个适配器的分工 <a class="header-anchor" href="#两个适配器的分工" aria-label="Permalink to &quot;两个适配器的分工&quot;">​</a></h3><ul><li>Vue：<code>XhSignaturePadRoot</code> 的默认插槽给出 <code>empty</code> / <code>paths</code> / <code>drawing</code> / <code>statusText</code> 与 <code>toSvg()</code> / <code>clear()</code>；也可以用 <code>useSignaturePad()</code> 自行获取。<code>XhSignaturePadGuide</code> 与 <code>XhSignaturePadPath</code> 必须写在 <code>XhSignaturePadControl</code> 内：SVG 命名空间由该子树带下，移出后会成为 HTML 元素，无法绘制。</li><li>Web Components：结构由作者编写（Light DOM，不投影插槽）。<code>&lt;xh-signature-pad&gt;</code> 上有 <code>clear()</code>、<code>toSvg()</code> 与只读的 <code>empty</code>；提交前取签名用 <code>toSvg()</code>，不需要缓存上一次 <code>draw-end</code>。</li><li>两侧的 <code>status</code> 部件内都不需要自行写文字：节点为空时由适配器填入内建文案；写了文字则以作者的为准。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>给清空按钮一句可见文字或稳定的图标语义，不只依靠一个叉。</li><li>清空之后安置焦点：按钮被禁用或收起时焦点会回到 <code>&lt;body&gt;</code>，键盘用户每清空一次就丢失一次位置。要么让按钮始终可按（本组件的默认做法），要么清空后显式把焦点交给下一个落点。</li><li>提交前用 <code>empty</code> 拦截：空签名与潦草签名是两回事，前者应在客户端拦截。</li><li>需要缓存待提交的 SVG 时按 <code>draw-end</code> 缓存：清空与表单重置同样会发出它，缓存不会停留在旧版本。不要嗅探清空按钮的点击。</li><li>存储的是 SVG 文本，不是位图。需要位图时在服务端渲染，不在前端截屏。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>把画布做得很窄：手写需要面积，过窄的画布只会产生无法辨认的字迹。</li><li>让签名成为唯一的确认方式却不提供替代路径，这是可达性问题。</li><li>把签名图当作身份凭证。它证明的是有人在画布上书写过，不是书写者的身份。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-signature-pad&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSignaturePadClearTrigger</code> <code>XhSignaturePadControl</code> <code>XhSignaturePadGuide</code> <code>XhSignaturePadHiddenInput</code> <code>XhSignaturePadLabel</code> <code>XhSignaturePadPath</code> <code>XhSignaturePadRoot</code> <code>XhSignaturePadStatus</code></td></tr><tr><td>组合式函数</td><td><code>useSignaturePad</code></td></tr><tr><td>状态机</td><td><code>signaturePadMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/signature-pad.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整块不可交互：不响应落笔，清空按钮也不可按下。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：已绘制的签名照常显示，但不可修改。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验未通过的标记，只改变外观与表单影子上的 aria-invalid。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；提供后表单影子才带 name 并参与提交。</td></tr><tr><td><code>drawing</code></td><td><code>SignaturePadDrawingOptions</code></td><td></td><td>笔迹外形。默认为 4px 恒定粗细。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;SignaturePadTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onDraw</code></td><td><code>(details: SignaturePadDrawDetails) =&gt; void</code></td><td></td><td>每收进一个点通知一次，清空与表单重置时也通知一次（路径为空）。</td></tr><tr><td><code>onDrawEnd</code></td><td><code>(details: SignaturePadDrawEndDetails) =&gt; void</code></td><td></td><td>签名定稿时通知一次并附带可直接提交的 SVG：抬笔、清空、表单重置三条路径都发出。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>draw</code></td><td><code>SignaturePadDrawDetails</code></td><td>笔迹变化时通知一次（含清空与表单重置）；detail 为 <code>{ paths: string[], path: string }</code></td></tr><tr><td><code>draw-end</code></td><td><code>SignaturePadDrawEndDetails</code></td><td>签名定稿时通知一次（抬笔、清空、表单重置）；detail 为 <code>{ paths: string[], svg: string }</code>，svg 可直接存储</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSignaturePadRoot</code></td><td><code>default</code></td><td><code>SignaturePadRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSignaturePadRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;SignaturePadRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>drawing</code> · <code>idle</code></p><p><strong>事件</strong>：<code>DRAW.START</code> · <code>DRAW.MOVE</code> · <code>DRAW.END</code> · <code>STROKES.CLEAR</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canDraw</code> · <code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>paths</code></td><td><code>readonly string[]</code></td><td>逐笔的填充轮廓 d 串，按落笔先后排列。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有任何笔迹。</td></tr><tr><td><code>drawing</code></td><td><code>boolean</code></td><td>笔正落在画布上。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>statusText</code></td><td><code>string</code></td><td>是否已签名的文案，写入 status 部件；适配器在作者未自行编写文字时把它填入节点。</td></tr><tr><td><code>toSvg</code></td><td><code>() =&gt; string</code></td><td>当前签名的独立 SVG 文档，与表单影子提交的是同一份；空签名为空串。</td></tr><tr><td><code>clear</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGuideProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPathProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getClearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getStatusProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>状态出口：一块 role=status 的活区域，签名与清空都会播报一次。</td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单出口：一份视觉隐藏的原生输入，随表单提交当前签名。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on clear-trigger, 未禁用且非只读</td><td>清空整块画布；按钮是原生 button，这两个键由平台翻成 click</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>held in clear-trigger, 未禁用且非只读</td><td>按住期间投影 data-pressed，与指针 :active 同一副按压面；抬起或失焦撤下</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>control</code></td><td><code>aria-label</code></td><td>translations?.label</td></tr><tr><td><code>control</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>control</code></td><td><code>role</code></td><td>&#39;img&#39;</td></tr><tr><td><code>guide</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>aria-label</code></td><td>translations?.clearTrigger</td></tr><tr><td><code>status</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>status</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>status</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr></tbody></table><ul><li>签名天然依赖指针，键盘和读屏无法完成。凡是要求签名的流程，必须同时提供一条不依赖指针的替代路径：打字签名、上传签名图或线下核验。只放一块画布等于把这些用户挡在流程之外。</li><li>画布报告为 <code>role=&quot;img&quot;</code>，不是控件：它不接受键盘、不进入 Tab 序列，伪装成控件只会让读屏用户进入无法操作的位置。</li><li>画布的名称来自 <code>label</code> 部件；未渲染标题时退回 <code>translations.label</code>。</li><li>是否已签名由 <code>status</code> 部件播报。画布是 <code>role=&quot;img&quot;</code>，名称固定，签名、清空、表单重置后读屏读出的都是同一句，用户无法确认笔迹是否保留。<code>status</code> 是 <code>role=&quot;status&quot;</code> 的活动区域，值每变一次播报一次，文案使用 <code>translations.statusEmpty</code> / <code>translations.statusSigned</code>。要求签名的表单请渲染它。</li><li>基准线是纯画面，带 <code>aria-hidden</code>，读屏不读。没有 <code>translations.guide</code> 文案：给装饰线命名只会增加无信息量的播报。</li><li>清空按钮是原生 <code>&lt;button&gt;</code>，Enter / Space 由平台激活；按钮内只有图标时读屏读 <code>translations.clearTrigger</code>。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/signature-pad.css</code> 使用 <code>[data-scope=&quot;signature-pad&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>guide</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>path</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-xh-action-size</code></td><td>&#39;sm&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-xh-action-variant</code></td><td>&#39;outline&#39;</td></tr><tr><td><code>status</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-signature-pad-aspect-ratio</code></td><td><code>control</code></td><td><code>aspect-ratio</code></td><td><code>default</code></td><td><code>5 / 2</code></td><td>signature-pad 的 control 部件 aspect-ratio 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-bg</code></td><td><code>control</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>signature-pad 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-bg-disabled</code></td><td><code>control</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-subtle</code></td><td>signature-pad 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-bg-readonly</code></td><td><code>control</code></td><td><code>background</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>readonly</code></td><td><code>--xh-bg-subtle</code></td><td>signature-pad 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-border</code></td><td><code>control</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-control</code></td><td>signature-pad 的 control 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-border-disabled</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>disabled</code></td><td><code>--xh-border-default</code></td><td>signature-pad 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-border-drawing</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>drawing</code></td><td><code>--xh-border-control-hover</code></td><td>signature-pad 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-bg</code></td><td><code>clear-trigger</code></td><td><code>background-color</code></td><td><code>default</code><br><code>focus-visible</code></td><td><code>--xh-_action-variant-bg-focus-visible</code><br><code>--xh-_action-variant-bg-rest</code></td><td>signature-pad 的 clear-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-bg-active</code></td><td><code>clear-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-bg-pressed</code></td><td>signature-pad 的 clear-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-bg-disabled</code></td><td><code>clear-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code></td><td><code>--xh-_action-variant-bg-disabled</code></td><td>signature-pad 的 clear-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-bg-hover</code></td><td><code>clear-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-_action-variant-bg-hover</code></td><td>signature-pad 的 clear-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-border</code></td><td><code>clear-trigger</code></td><td><code>border</code><br><code>border-color</code></td><td><code>default</code><br><code>focus-visible</code></td><td><code>--xh-_action-variant-border-focus-visible</code><br><code>--xh-_action-variant-border-rest</code></td><td>signature-pad 的 clear-trigger 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-border-hover</code></td><td><code>clear-trigger</code></td><td><code>border-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-border-hover</code><br><code>--xh-_action-variant-border-pressed</code></td><td>signature-pad 的 clear-trigger 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-fg</code></td><td><code>clear-trigger</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_action-variant-fg-focus-visible</code><br><code>--xh-_action-variant-fg-hover</code><br><code>--xh-_action-variant-fg-pressed</code><br><code>--xh-_action-variant-fg-rest</code></td><td>signature-pad 的 clear-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-fg-empty</code></td><td><code>clear-trigger</code></td><td><code>color</code></td><td><code>empty</code></td><td><code>--xh-fg-muted</code></td><td>signature-pad 的 clear-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-font-size</code></td><td><code>clear-trigger</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-font-size</code></td><td>signature-pad 的 clear-trigger 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-gap</code></td><td><code>clear-trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_action-profile-gap</code></td><td>signature-pad 的 clear-trigger 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-h</code></td><td><code>clear-trigger</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-visual-size</code></td><td>signature-pad 的 clear-trigger 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-icon-size</code></td><td><code>clear-trigger</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-glyph-size</code></td><td>signature-pad 的 clear-trigger 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-px</code></td><td><code>clear-trigger</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_action-profile-padding-inline</code></td><td>signature-pad 的 clear-trigger 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-radius</code></td><td><code>clear-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>signature-pad 的 clear-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-clear-shadow-hover</code></td><td><code>clear-trigger</code></td><td><code>box-shadow</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>none</code></td><td>signature-pad 的 clear-trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-control-border-invalid</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>signature-pad 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-gap</code></td><td><code>label</code><br><code>root</code></td><td><code>gap</code><br><code>margin-block-end</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>signature-pad 的 label、root 部件 gap、margin-block-end 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-guide-stroke</code></td><td><code>guide</code></td><td><code>stroke</code></td><td><code>default</code></td><td><code>--xh-border-control</code></td><td>signature-pad 的 guide 部件 stroke 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-ink</code></td><td><code>path</code></td><td><code>fill</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>signature-pad 的 path 部件 fill 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>signature-pad 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-label-fg-disabled</code></td><td><code>label</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>signature-pad 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>signature-pad 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>signature-pad 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-label-gap</code></td><td><code>label</code></td><td><code>margin-block-end</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>signature-pad 的 label 部件 margin-block-end 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-radius</code></td><td><code>control</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>signature-pad 的 control 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-status-fg</code></td><td><code>status</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>signature-pad 的 status 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-signature-pad-status-font-size</code></td><td><code>status</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>signature-pad 的 status 部件 font-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>border-color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><ul><li>画布宽度铺满外层容器，高度由宽高比（<code>--xh-signature-pad-aspect-ratio</code>，默认 5 / 2）决定，窄屏上自动变矮。</li><li>签名过程中转屏、拖动面板改变宽度时，已有笔迹按 <code>viewBox</code> 整体缩放，后续新笔与它落在同一套坐标。</li><li>触摸设备上画布关闭浏览器的滚动与缩放手势，避免手指划动时页面滚动。</li></ul><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>画布与基准线不区分左右：笔迹按落笔坐标记录，方向由书写者决定。</li><li>标题与清空按钮的排布跟随文档方向，皮肤全部使用逻辑属性。</li></ul>',66))])}const P=r(s,[["render",h]]);export{m as __pageData,P as default};
